<?php
require __DIR__.'/private/core.php';
if(is_file(__DIR__.'/private/installed.lock')){http_response_code(403);exit('Instalación bloqueada. Elimine install.php del servidor.');}
$error='';$done=false;
if($_SERVER['REQUEST_METHOD']==='POST')try{
 checkcsrf();if(str_starts_with($config['install_key'],'CAMBIAR')||strlen($config['install_key'])<32||!hash_equals($config['install_key'],(string)($_POST['key']??'')))throw new RuntimeException('Clave de instalación incorrecta o sin configurar.');
 $email=field('email',190);$pass=field('password',200);if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<12)throw new RuntimeException('Correo válido y contraseña de al menos 12 caracteres requeridos.');
 $lock=fopen(__DIR__.'/private/install.mutex','c');if(!$lock||!flock($lock,LOCK_EX))throw new RuntimeException('No se pudo bloquear la instalación.');
 foreach(explode(';',file_get_contents(__DIR__.'/private/schema.sql')) as $sql)if(trim($sql)!=='')db()->exec($sql);
 if(q('SELECT COUNT(*) FROM sc_users')->fetchColumn()>0)throw new RuntimeException('Ya existe un administrador. No se puede reinstalar.');
 db()->beginTransaction();
 q('INSERT INTO sc_users(email,password,role) VALUES (?,?,?)',[$email,password_hash($pass,PASSWORD_DEFAULT),'admin']);
 foreach(['name'=>'Condominio Sofía Carmona 301','address'=>'Sofía Carmona 301 · La Granja','headline'=>'Un lugar que construimos juntos.','intro'=>'Bienvenidos a nuestro espacio de comunidad. Información clara, canales de atención y todo lo que necesitas para vivir mejor.','hero'=>'media/portada.jpg','contact'=>'Contacta a la administración mediante el formulario de consultas.','privacy'=>'Los datos se utilizan para recibir, gestionar y responder solicitudes. Acceden la administración o el encargado Ley Karin según el tipo de caso. No se publican. Puedes solicitar acceso, rectificación o eliminación mediante Consultas, sujeto a las obligaciones de conservación aplicables. Evita enviar datos de terceros que no sean necesarios.','karin_contact'=>'Pendiente de designación por la administración.','karin_enabled'=>'0'] as $k=>$v)q('INSERT INTO sc_settings(name,value) VALUES (?,?)',[$k,$v]);
 foreach(require __DIR__.'/private/seed.php' as $row)q('INSERT INTO sc_content(kind,title,body,image,link) VALUES (?,?,?,?,?)',$row);
 db()->commit();file_put_contents(__DIR__.'/private/installed.lock',date(DATE_ATOM));$done=true;
}catch(Throwable $ex){if(isset($lock)&&db()->inTransaction())db()->rollBack();$error=$ex instanceof RuntimeException&&!($ex instanceof PDOException)?$ex->getMessage():'No se pudo instalar. Revisa los datos MySQL y los permisos; consulta el registro de errores.';error_log($ex->getMessage());}
?><!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="stylesheet" href="assets/style.css"><title>Instalar comunidad</title><main class="narrow"><p class="eyebrow">SOFÍA CARMONA · INSTALACIÓN</p><h1>Tu comunidad, conectada.</h1><?php if($done):?><div class="notice">Instalación completada. Elimina install.php desde cPanel.</div><a class="button" href="index.php?p=login">Entrar al panel</a><?php else:?><p>Configura MySQL en private/config.php y crea tu cuenta. No hay contraseñas predeterminadas.</p><?php if($error):?><p class="notice"><?=e($error)?></p><?php endif;?><form method="post"><?php csrf();?><label>Clave de instalación<input name="key" type="password" required></label><label>Correo del administrador<input name="email" type="email" required></label><label>Contraseña (mínimo 12 caracteres)<input name="password" type="password" minlength="12" required></label><button>Instalar sitio</button></form><?php endif;?></main></html>
